# Process helpers for the benchmark, test and tool scripts.
#
# A script that starts programs (blitzcc, compiled Blitz programs, xvfb-run, ffmpeg, ...) must never leave them running when it
# ends, no matter how it ends: normal exit, an exception, a timeout, Ctrl-C, SIGTERM / SIGHUP, a closed console window, or the
# parent being killed. A forgotten benchmark process makes every later measurement wrong, so the script that started a process
# always terminates it, without asking.
#
#   Windows:  every child is put into one Job Object with JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE. The operating system kills the
#             whole job (children and grandchildren) when the script dies, even if it was killed hard. Without a job (assigning
#             failed) `taskkill /T /F` is used instead.
#   POSIX:    every child gets its own session / process group, which is killed as a whole (os.killpg). A small watcher
#             process kills the groups when the script dies without cleaning up (SIGKILL).
#
# `run` and `Popen` are drop-in replacements for `subprocess.run` and `subprocess.Popen`:
#
#   import procutil
#   result = procutil.run([exe], capture_output=True, text=True, timeout=600)

import atexit
import os
import signal
import subprocess
import sys
import threading

CalledProcessError = subprocess.CalledProcessError
TimeoutExpired = subprocess.TimeoutExpired
CompletedProcess = subprocess.CompletedProcess
PIPE = subprocess.PIPE
STDOUT = subprocess.STDOUT
DEVNULL = subprocess.DEVNULL

WINDOWS = os.name == "nt"

_lock = threading.Lock()
_children = {}  # pid -> Popen
_job = None
_job_tried = False
_hooked = False


# --- Windows job object -------------------------------------------------------------------------------------------------------


def _make_job():
    import ctypes
    from ctypes import wintypes

    class BASIC(ctypes.Structure):
        _fields_ = [("PerProcessUserTimeLimit", ctypes.c_int64), ("PerJobUserTimeLimit", ctypes.c_int64),
                    ("LimitFlags", wintypes.DWORD), ("MinimumWorkingSetSize", ctypes.c_size_t),
                    ("MaximumWorkingSetSize", ctypes.c_size_t), ("ActiveProcessLimit", wintypes.DWORD),
                    ("Affinity", ctypes.c_size_t), ("PriorityClass", wintypes.DWORD), ("SchedulingClass", wintypes.DWORD)]

    class IO(ctypes.Structure):
        _fields_ = [(n, ctypes.c_uint64) for n in ("ReadOperationCount", "WriteOperationCount", "OtherOperationCount",
                                                    "ReadTransferCount", "WriteTransferCount", "OtherTransferCount")]

    class EXTENDED(ctypes.Structure):
        _fields_ = [("BasicLimitInformation", BASIC), ("IoInfo", IO), ("ProcessMemoryLimit", ctypes.c_size_t),
                    ("JobMemoryLimit", ctypes.c_size_t), ("PeakProcessMemoryUsed", ctypes.c_size_t),
                    ("PeakJobMemoryUsed", ctypes.c_size_t)]

    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    k32.CreateJobObjectW.restype = wintypes.HANDLE
    k32.CreateJobObjectW.argtypes = [ctypes.c_void_p, wintypes.LPCWSTR]
    k32.SetInformationJobObject.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
    k32.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
    k32.OpenProcess.restype = wintypes.HANDLE
    k32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    k32.CloseHandle.argtypes = [wintypes.HANDLE]

    job = k32.CreateJobObjectW(None, None)
    if not job:
        return None
    info = EXTENDED()
    info.BasicLimitInformation.LimitFlags = 0x2000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
    if not k32.SetInformationJobObject(job, 9, ctypes.byref(info), ctypes.sizeof(info)):  # JobObjectExtendedLimitInformation
        return None

    def assign(pid):
        handle = k32.OpenProcess(0x0001 | 0x0100, False, pid)  # PROCESS_TERMINATE | PROCESS_SET_QUOTA
        if not handle:
            return False
        try:
            return bool(k32.AssignProcessToJobObject(job, handle))
        finally:
            k32.CloseHandle(handle)

    return assign


def _assign_to_job(pid):
    global _job, _job_tried
    if not _job_tried:
        _job_tried = True
        try:
            _job = _make_job()
        except Exception:
            _job = None
    return bool(_job and _job(pid))


# --- killing ------------------------------------------------------------------------------------------------------------------


def kill_tree(process):
    """Terminates a child and everything it started, then reaps it."""
    if process.poll() is None or not WINDOWS:
        try:
            if WINDOWS:
                subprocess.run(["taskkill", "/T", "/F", "/PID", str(process.pid)], stdout=subprocess.DEVNULL,
                               stderr=subprocess.DEVNULL)
                process.kill()
            else:
                os.killpg(process.pid, signal.SIGKILL)  # the child is its own group leader
        except (ProcessLookupError, PermissionError, OSError):
            pass
    try:
        process.wait(timeout=10)
    except Exception:
        pass
    with _lock:
        _children.pop(process.pid, None)
    if not WINDOWS:
        _watch(process.pid, False)  # the group is gone, its number may be reused


def kill_all():
    """Terminates every child this script started and that is still registered."""
    with _lock:
        alive = list(_children.values())
    for process in alive:
        kill_tree(process)


def _on_signal(number, frame):
    kill_all()
    signal.signal(number, signal.SIG_DFL)
    os.kill(os.getpid(), number)


def _hook():
    global _hooked
    if _hooked:
        return
    _hooked = True
    atexit.register(kill_all)
    if threading.current_thread() is not threading.main_thread():
        return
    names = ["SIGTERM", "SIGHUP", "SIGBREAK"]  # SIGINT stays a KeyboardInterrupt, which run() handles
    for name in names:
        number = getattr(signal, name, None)
        if number is not None:
            try:
                signal.signal(number, _on_signal)
            except (ValueError, OSError):
                pass


# Started once per script. It reads the process groups of the children from a pipe and kills all of them when the pipe closes,
# which is what happens when the script dies in a way that runs no cleanup (SIGKILL, power-cut of the terminal, ...).
_WATCHER = """
import os, signal, sys
groups = set()
for line in sys.stdin:
    number = int(line)
    groups.discard(-number) if number < 0 else groups.add(number)
for group in groups:
    try:
        os.killpg(group, signal.SIGKILL)
    except OSError:
        pass
"""
_watcher = None


def _watch(pid, add=True):
    global _watcher
    try:
        if _watcher is None:
            _watcher = subprocess.Popen([sys.executable, "-c", _WATCHER], stdin=subprocess.PIPE, start_new_session=True)
        _watcher.stdin.write(b"%d\n" % (pid if add else -pid))
        _watcher.stdin.flush()
    except Exception:
        pass


# --- spawning -----------------------------------------------------------------------------------------------------------------


def Popen(args, **kwargs):
    """subprocess.Popen whose process (and its descendants) die with this script."""
    _hook()
    if WINDOWS:
        kwargs["creationflags"] = kwargs.get("creationflags", 0) | subprocess.CREATE_NEW_PROCESS_GROUP
    else:
        kwargs.setdefault("start_new_session", True)
    process = subprocess.Popen(args, **kwargs)
    if WINDOWS:
        _assign_to_job(process.pid)  # on failure kill_tree() still has taskkill /T
    else:
        _watch(process.pid)
    with _lock:
        _children[process.pid] = process
    return process


def run(args, *, input=None, capture_output=False, timeout=None, check=False, **kwargs):
    """subprocess.run that terminates the whole process tree on timeout, Ctrl-C or any other exception."""
    if input is not None:
        kwargs["stdin"] = PIPE
    if capture_output:
        kwargs["stdout"] = PIPE
        kwargs["stderr"] = PIPE
    with Popen(args, **kwargs) as process:
        try:
            stdout, stderr = process.communicate(input, timeout=timeout)
        except BaseException as error:
            kill_tree(process)
            if isinstance(error, TimeoutExpired):
                try:
                    error.stdout, error.stderr = process.communicate(timeout=5)
                except Exception:
                    pass
            raise
        finally:
            with _lock:
                _children.pop(process.pid, None)
            if not WINDOWS:
                _watch(process.pid, False)
        code = process.poll()
    if check and code:
        raise CalledProcessError(code, args, output=stdout, stderr=stderr)
    return CompletedProcess(process.args, code, stdout, stderr)
